function vjD3JS_tree_named( viewer )
{
    vjD3View.call(this,viewer);
    var thiSS=this;
    var i = 0;
    var vCcl=10;

    this.update=function(source) {
    
        var duration = 750;
        
        var nodes = this.tree.nodes(this.root).reverse();
        var links = this.tree.links(nodes);
        
        nodes.forEach(function(d) { d.y = d.depth * 180; });
        
        var node = this.d3svg.selectAll("g.node")
          .data(nodes, function(d) { return d.id || (d.id = ++i); });
        
        var nodeEnter = node.enter().append("g")
          .attr("class", "node")
          .attr("transform", function(d) { return "translate(" + source.y0 + "," + source.x0 + ")"; })
          .on("click", thiSS.click);
        
        
        nodeEnter.append("text")
          .attr("x", function(d) { return 2; })
          .attr("dy", ".35em")
          .attr("text-anchor", function(d) { return d.children || d._children ? "start" : "start"; })
          .text(function(d) {d._txt=this; return d.name; })
          .style("fill-opacity", 1e-6)
          .attr("class", function(d) {if (d.url != null) { return 'hyper'; }})
          .on("click", function (d) {}) 
        ;
        nodes.forEach(function(node) {
            node.szx=node._txt.getComputedTextLength();
        });


        var rad=15, dim=6, t="" ,sang=4;
        for(var j=sang;j<sang+dim;++j) {
            var angl=sang+j*2*3.1415926/dim;
            var xx=rad*Math.sin(angl);
            var yy=rad*Math.cos(angl)
            t+=xx+","+yy+" ";
        }
        
        nodeEnter.append("circle")
            .attr("id","crc-right")
            .attr("r", 1e-6);
        
        nodeEnter.append("polyline")
            .attr("id","crc-lft")
            .attr("points",t)
            .attr("class","node")
            .style("fill", "none")
            .style("stroke", "#ffffff")
            ;
    
        
        var nodeUpdate = node.transition()
          .duration(duration)
          .attr("transform", function(d) { return "translate(" + d.y + "," + d.x + ")"; });
        
        nodeUpdate.select("#crc-lft")
          .style("stroke-opacity",function(d) {return (d.children ) ? 1  : ((d._children) ? 1 : 0); })
          .style("stroke",function(d) {return (d.children ) ? "#bfbfbf"  : ((d._children) ? "#0047AB" : "#ffffff"); })
          ;
        nodeUpdate.select("#crc-right")
          .attr("r", vCcl/2)
          .style("cx", function(d) { return d.szx+vCcl*3/2; })
          .style("stroke-opacity",function(d) {return (d.children || d._children) ? 1 : 0; })
          ;
        
        nodeUpdate.select("text")
          .style("fill-opacity", 1);
        
        var nodeExit = node.exit().transition()
          .duration(duration)
          .attr("transform", function(d) { return "translate(" + source.y + "," + source.x + ")"; })
          .remove();
        
        nodeExit.select("text")
          .style("fill-opacity", 1e-6);
        
        var link = this.d3svg.selectAll("path.link")
          .data(links, function(d) { return d.target.id; });
        
        link.enter().insert("path", "g")
          .attr("class", "link")
          .attr("d", function(d) {
            var o = {x: source.x0, y: source.y0};
            return thiSS.diagonal({source: o, target: o});
          })
          ;

        link.transition()
          .duration(duration)
          .attr("d", function(d) {
            return thiSS.diagonal({source: {x: d.source.x, y: d.source.y+d.source.szx+vCcl*2}, target: {x: d.target.x, y: d.target.y-vCcl*1.4}});
          });
        
        link.exit().transition()
          .duration(duration)
          .attr("d", function(d) {
            var o = {x: source.x, y: source.y};
            return thiSS.diagonal({source: o, target: o});
          })
          .remove();
        
        nodes.forEach(function(d) {
            d.x0 = d.x;
            d.y0 = d.y;
        });
    }
    
    this.click=function(d) {
        if (d.children) {
            d._children = d.children;
            d.children = null;
        } else {
            d.children = d._children;
            d._children = null;
        }
        thiSS.update(d);
    }


    this.d3Compose=function( viewer , content )
    {
        var margin = {top: 10, right: 10, bottom: 10, left:10},
        width = 950 - margin.right - margin.left,
        height = 800 - margin.top - margin.bottom;
    
        d3.select(self.frameElement).style("height", "800px");
        
        var svg = this.d3svg
        .attr("width", width + margin.right + margin.left)
        .attr("height", height + margin.top + margin.bottom)
        .append("g")
        .attr("transform", "translate(" + margin.left + "," + margin.top + ")");

        this.tree = d3.layout.tree().size([height, width]);
        this.diagonal = d3.svg.diagonal().projection(function(d) { return [d.y, d.x]; });
    
    
        this.root = treeData[0];
        this.root.x0 = height / 2;
        this.root.y0 = 0;
        
        this.update(this.root);
                
    }

}

 